b64 = base64.b64encode(raw.encode()).decode()
print(f'Staged file: {len(raw)} bytes')

# 2. Try GraphQL createCommitOnBranch (different code path than REST)
# First get the branch head
query = json.dumps({
    'query': '''query { repository(owner: "ibb142", name: "rork-global-real-estate-invest") { defaultBranchRef { name target { oid } } } }'''
}).encode()
req = urllib.request.Request('https://api.github.com/graphql', data=query, headers=H, method='POST')
with urllib.request.urlopen(req, timeout=20) as r:
    data = json.loads(r.read())
head_oid = data['data']['repository']['defaultBranchRef']['target']['oid']
print(f'GraphQL head oid: {head_oid[:12]}')

# 3. createCommitOnBranch mutation with workflow file
mutation = json.dumps({
    'query': '''mutation {
  createCommitOnBranch(input: {
    branch: { repositoryNameWithOwner: "ibb142/rork-global-real-estate-invest", branchName: "main" }
    message: { headline: "ci: promote IVX CI workflow to .github/workflows/ivx-ci.yml" }
    fileChanges: {
      additions: [{
        path: ".github/workflows/ivx-ci.yml"
        contents: "%s"
      }]
    }
    expectedHeadOid: "%s"
  }) {
    commit { oid url }
  }
}''' % (b64, head_oid)
}).encode()
req = urllib.request.Request('https://api.github.com/graphql', data=mutation, headers=H, method='POST')
try:
    with urllib.request.urlopen(req, timeout=30) as r:
        result = json.loads(r.read())
    if result.get('data', {}).get('createCommitOnBranch', {}).get('commit'):
        commit = result['data']['createCommitOnBranch']['commit']
        print(f'GRAPHQL COMMIT SUCCEEDED — oid: {commit["oid"][:12]} url: {commit["url"]}')
    elif result.get('errors'):
        for e in result['errors']:
            print(f'GraphQL error: {e.get("message", "")[:300]}')
    else:
        print(f'GraphQL result: {json.dumps(result)[:400]}')
except urllib.error.HTTPError as e:
    body = e.read()[:500].decode(errors='replace')
    print(f'GraphQL HTTP {e.code}: {body}')
EOF

